-- Schéma minimal de recette isolée V30 : aucun accès à une base distante.
create role anon;
create role authenticated;
create role service_role;
create table profiles(user_id uuid primary key,nickname text,avatar text,avatar_config jsonb,heart_club_id text);
create table player_league(user_id uuid primary key,echelon int,joined_at timestamptz default now());
create table bets(id uuid primary key,user_id uuid,stake numeric,odds numeric,counts_general boolean default true,bet_type text default 'single',selections jsonb default '[]',status text default 'pending',payout numeric,week_start date default current_date,placed_at timestamptz default now(),settled_at timestamptz);
create table player_accounts(user_id uuid primary key,bankroll numeric,updated_at timestamptz);
create table daily_picks(id bigint generated by default as identity primary key,user_id uuid,day date,match_id text,pick text,odd numeric,status text default 'pending',points numeric default 0,placed_at timestamptz default now(),settled_at timestamptz,unique(user_id,match_id));
create table league_entries(id bigint generated always as identity primary key,bet_id uuid,user_id uuid,league text default 'general',points numeric,week_start date,season text,settled_at timestamptz,daily_pick_id bigint unique,unique(bet_id,league));
create table league_seasons(season text primary key,status text);
create table special_leagues(id text primary key,kind text,open boolean,season_start date,season_end date);
create table league_members(user_id uuid,league_id text);
create table special_rounds(id text primary key,league_id text,match_ids jsonb,starts_at timestamptz,ends_at timestamptz,anchor text,free_slots int);
create table special_picks(id bigint generated by default as identity primary key,bet_id uuid,user_id uuid,league_id text,round_id text,match_ids text[],kind text,source text,key text,odd numeric,status text default 'pending',points numeric default 0,placed_at timestamptz default now(),settled_at timestamptz);
create table private_league_members(user_id uuid,league_id uuid,joined_at timestamptz default now());
create table daily_challenges(day date primary key,picks jsonb);
create table fixtures(id text primary key,voided boolean default false,completed boolean default false,kickoff timestamptz);
create function football_season(p_date timestamptz default now()) returns text language sql stable as $$ select case when extract(month from p_date at time zone 'Europe/Paris') >= 7 then extract(year from p_date at time zone 'Europe/Paris')::int else extract(year from p_date at time zone 'Europe/Paris')::int-1 end || '-' || case when extract(month from p_date at time zone 'Europe/Paris') >= 7 then extract(year from p_date at time zone 'Europe/Paris')::int+1 else extract(year from p_date at time zone 'Europe/Paris')::int end $$;
create function is_private_member(p_league uuid) returns boolean language sql as $$ select true $$;
-- Reproduire les types de la vue existante pour détecter les changements incompatibles.
create view daily_participation as select user_id,''::text as season,0::bigint as played,0::bigint as good,0::bigint as offered from player_league;
create table standings(season text,user_id uuid,group_id bigint,points numeric default 0,picks int default 0,wins int default 0,roi numeric default 0,form text default '',daily_good int default 0,qualified boolean default true,rank int default 1,prev_rank int,snapshot_date date,updated_at timestamptz default now(),primary key(season,user_id));
create table season_results(season text,user_id uuid,points numeric,group_rank int,to_echelon int,outcome text,primary key(season,user_id));
create table special_standings(league_id text,scope text,user_id uuid,points numeric default 0,picks int default 0,wins int default 0,roi numeric default 0,rank int default 1,played_rounds int default 0,updated_at timestamptz default now(),primary key(league_id,scope,user_id));
